import crypto from 'crypto';

/**
 * Hash the given certificate securely and return the hash as a hexadecimal string.
 *
 *
 * @param {string} cert - The certificate to be hashed.
 * @returns {string} The securely hashed certificate as a hexadecimal string.
 */
function hash_certificate(cert) {
  // Input validation to prevent potential denial-of-service attacks.
  // If the input is not a string or is excessively large, return an empty string.
  // A reasonable limit for certificate size should be established based on expected usage.
  // For this example, we'll set an arbitrary limit of 1MB (1024 * 1024 bytes).
  const MAX_CERT_SIZE = 1024 * 1024; // 1MB

  if (typeof cert !== 'string' || cert.length === 0 || cert.length > MAX_CERT_SIZE) {
    return '';
  }

  const hash = crypto.createHash('sha256');
  hash.update(cert);
  return hash.digest('hex');
}
